/** The ledger's execution tracking, created (or completed, for a ledger restored from an earlier version) on first use. */
export function trackingOf(ledger: ObjectiveLedger): ExecutionTracker {
  ledger.execution = normalizeTracking(ledger.execution);
  return new ExecutionTracker(ledger.execution);
}

const now = () => new Date().toISOString();
const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
const clip = (text: string, max: number) => (text.length <= max ? text : `${text.slice(0, max - 1)}…`);

/**
 * Acceptance criteria as written: top-level numbered items (`1.`, `2)`, `R3:`) of the objective. Each keeps its
 * heading line; the full wording stays in the verbatim objective. Fewer than two items means the objective is a
 * single request and is tracked as one requirement.
    objectiveSha256: sha256(objective),
    startedAt: at,
    requirements: seedRequirements(objective).map((seed) => ({
      ...seed,
      status: "open" as const,
      source: "objective" as const,
      evidence: [],
      updatedAt: at,
    })),
    scopeChanges: [],
    steering: [],
    verification: [],
    continuation: { segments: 1, totalSteps: 0, lastProgressStep: 0 },
    amendments: [],
    execution: createTracking(),
  };
}

/**
 * Requirements an operator follow-up adds to the objective it continues: its numbered items, appended after the
 * existing ones (an amendment never removes or rewrites what was asked before).
 */
export function amendObjective(ledger: ObjectiveLedger, prompt: string, at = now()): Requirement[] {
  ledger.amendments.push({ at, text: prompt });
  const seeds = seedRequirements(prompt);
  if (seeds.length < 2) return [];
  const base = ledger.requirements.filter((r) => r.source === "objective").length;
  const added = seeds.map((seed, i) => ({
    id: `R${base + i + 1}`,
    text: seed.text,
    detail: seed.detail,
    ...(seed.kind ? { kind: seed.kind } : {}),
    ...(seed.verifier ? { verifier: seed.verifier, verifierSource: seed.verifierSource } : {}),
    status: "open" as const,
    source: "objective" as const,
    evidence: [],
  }

  /** Saves the verification-config attempts recorded since the last save, so a resumed session and its export still show them. */
  private syncVerificationAttempts(): void {
    const count = this.bridge.getSecurityManager().getVerificationAttempts().length;
    if (count === this.persistedVerificationAttempts) return;
    this.persistedVerificationAttempts = count;
    this.persistProgress({ verificationConfigAttempts: true });
  }

  private persistProgress(progress: { verificationConfigAttempts?: boolean; messages?: boolean; unverifiedChangesPending?: boolean; changeBaseline?: ChangeBaseline | null }): void {
    if (!this.durable || this.restoringConversation) return;
    try {
      if (this.stateManager && !this.stateManager.hasTaskState(this.currentTaskId)) this.checkpointDurableState();
      else this.stateManager?.recordProgress(this.currentTaskId, {
        // The ledger travels with the conversation: steering applied as a message is also a ledger record.
        ...(progress.messages ? {
          messages: this.messages,
          findings: this.getFindings(),
          objective: this.objective ?? null,
          unverifiedChangesPending: this.hasPendingModifications,
          changeBaseline: this.changeBaseline
            ? {
                command: this.changeBaseline.command,
                failed: this.changeBaseline.failed,
                tests: this.changeBaseline.tests ? Object.fromEntries(this.changeBaseline.tests) : null,
                verifier: this.changeBaseline.verifier ? Object.fromEntries(this.changeBaseline.verifier) : null,
                ...(this.changeBaseline.verifierUnbindableReason ? { verifierUnbindableReason: this.changeBaseline.verifierUnbindableReason } : {}),
                trustedDeliverables: this.changeBaseline.trustedDeliverables,
                ...(this.changeBaseline.tddRedVerifier ? { tddRedVerifier: Object.fromEntries(this.changeBaseline.tddRedVerifier) } : {}),
                ...(this.changeBaseline.tddRedTests ? { tddRedTests: Object.fromEntries(this.changeBaseline.tddRedTests) } : {}),
                at: this.changeBaseline.at,
              }
            : (this.changeBaseline === null
              ? this.untrustedRecoveredBaseline ?? null
              : this.untrustedRecoveredBaseline ?? undefined),
        } : {}),
        ...(progress.unverifiedChangesPending !== undefined ? { unverifiedChangesPending: progress.unverifiedChangesPending } : {}),
        ...(progress.verificationConfigAttempts ? { verificationConfigAttempts: this.bridge.getSecurityManager().getVerificationAttempts() } : {}),
        ...(progress.changeBaseline !== undefined ? {
          changeBaseline: progress.changeBaseline
          await this.drainCompactionQueue(currentStep, signal);
        } catch (err) {
          if (!(err instanceof CompactionCommitError)) throw err;
          persistenceFailure = err.outcome.message;
          return false;
        }
        return true;
      };
      if (!(await drainQueuedCompactions())) break;
      if (budget && currentStep > 1 && (currentStep - 1) % segmentSteps === 0) {
        segment++;
        if (this.objective) this.objective.continuation.segments = segment;
        withDurableSync(() => {
          try {
            this.checkpointDurableState(`continuation: segment ${segment} begins at step ${currentStep}`);
          } catch (err: any) {
            this.reportPersistenceFailure("continuation", err);
          }
          this.persistProgress({ messages: true });
        });
        console.warn(pc.dim(`↻ Continuing automatically: segment ${segment} begins at step ${currentStep}; the work is still progressing.`));
      }
      const cumulativeStep = tracker.beginStep();
      if (this.objective && this.durable) this.objective.continuation.totalSteps = tracker.data.cumulativeSteps;
      const stepStateBefore = stateNow;
