        NEXUS_RELEASES_API: "http://127.0.0.1:1/api/releases",
        NEXUS_RELEASE_BASE_URL: "http://127.0.0.1:1/download",
      },
    });
    assert.equal(res.code, 2);
    assert.match(res.stderr, /could not query GitHub releases API/);
  });

