item.aggregated_output:
 * `-run`, `FILTER=`), a pytest node id (`file.py::test`), or a positional test name for `cargo test`. A filtered run
 * can show that a test passes, not that nothing else broke.
 */
export function isFilteredVerifierCommand(command: string): boolean {
  if (!command) return false;
  if (/(?:^|\s)(?:-t|-k|--grep|-g)(?:\s|=)\S/.test(command)) return true;
  if (/(?:^|\s)(?:--test-name-pattern|--testNamePattern|-run|--run)(?:\s|=)\S/.test(command)) return true;
  if (/(?:^|\s)FILTER=\S/.test(command)) return true;
  if (/\S\.py::\S/.test(command)) return true;
  if (/(?:^|\s)--(?:$|\s+[^-]\S*)/.test(command)) return true;
  const cargo = command.match(/\bcargo\s+test\b(.*)$/);
  if (cargo) {
    const tokens = cargo[1].trim().split(/\s+/).filter(Boolean);
    const takesValue = new Set(["--manifest-path", "-p", "--package", "--features", "-F", "--target", "--profile", "-j", "--jobs", "--bin", "--test", "--example", "--bench", "--exclude", "--target-dir", "--color", "--message-format"]);
    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      if (token === "--") return tokens.slice(i + 1).some((t) => !t.startsWith("-"));
      if (takesValue.has(token)) {
        i++;
        continue;
      }
      if (token.startsWith("-") || /[;&|]/.test(token)) {
        if (/[;&|]/.test(token)) break;
        continue;
      }
      return true;
    }
  }
  return false;
}

/**
 * Whether a test run's output shows that at least one test executed. Runners that report counts are read (node:test,
 * cargo, pytest, unittest, jest/vitest, mocha, go); output with no recognisable report — including no output — is not evidence.
 * Skipped tests are subtracted; a run where all tests were skipped returns false.
 */
export function hasExecutedTests(rawOutput: string): boolean {
  if (!rawOutput) return false;

  // 1. node:test
  const nodeTests = [...rawOutput.matchAll(/ℹ\s+tests\s+(\d+)/g)];
  if (nodeTests.length) {
    const totalTests = nodeTests.reduce((sum, m) => sum + Number(m[1]), 0);
    const pass = [...rawOutput.matchAll(/ℹ\s+pass\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
    const fail = [...rawOutput.matchAll(/ℹ\s+fail\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
    const hasPassOrFail = /ℹ\s+(?:pass|fail)\s+\d+/.test(rawOutput);
    if (hasPassOrFail) return pass + fail > 0;
    const skipped = [...rawOutput.matchAll(/ℹ\s+skipped\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
    const todo = [...rawOutput.matchAll(/ℹ\s+todo\s+(\d+)/g)].reduce((sum, m) => sum + Number(m[1]), 0);
    return totalTests - skipped - todo > 0;
  }

  // Node 20's default node:test reporter uses TAP summary lines; Node 22+ may emit the spec summary above.
  const nodeTap = rawOutput.match(
    /(?:^|\n)# tests (\d+)\r?\n# suites \d+\r?\n# pass (\d+)\r?\n# fail (\d+)\r?\n# cancelled (\d+)\r?\n# skipped (\d+)\r?\n# todo (\d+)(?:\r?\n# duration_ms [\d.]+)?(?=\r?\n|$)/
  );
  if (nodeTap) {
    const passed = Number(nodeTap[2]);
    const failed = Number(nodeTap[3]);
    return passed + failed > 0;
  }

  // 2. Cargo (Rust)
  const cargo = [...rawOutput.matchAll(/test result: \w+\. (\d+) passed; (\d+) failed/g)];
  if (cargo.length) return cargo.some((m) => Number(m[1]) + Number(m[2]) > 0);

  // 3. Jest
  const jest = rawOutput.match(/Tests:\s+(?:(\d+)\s+failed,?\s*)?(?:(\d+)\s+passed,?\s*)?(?:(\d+)\s+skipped,?\s*)?(\d+)\s+total/);
  if (jest) {
    const failed = Number(jest[1] || 0);
    const passed = Number(jest[2] || 0);
    return passed + failed > 0;
  }

  // 4. Vitest
  const vitestPassed = rawOutput.match(/\bTests\s+.*?(\d+)\s+passed/);
];

const ANSI = /\u001b(?:\[[0-9;?]*[ -/]*[@-~]|\][^\u0007\u001b]*(?:\u0007|\u001b\\))/g;
const stripAnsi = (text: string): string => text.replace(ANSI, "");
/** Verifier-controlled text made safe to carry: secrets redacted, then controls and bidi overrides made visible, then clipped. */
const safeVerifierText = (text: string, max: number): string => clip(safeTerminal(text), max);

/** Names of failing tests in TAP, node:test, jest, vitest, mocha, unittest, pytest, go and cargo output. */
export function failingTestNames(output: string): string[] {
  return failingTestScan(output).names;
}

function failingTestScan(output: string): { names: string[]; total: number } {
  const names = new Set<string>();
  for (const raw of stripAnsi(output).split(/\r?\n/)) {
    const line = raw.trim();
    for (const re of NAME_PATTERNS) {
      const name = re.exec(line)?.[1];
      if (name && !/^\d+ (?:tests?|failed)\b/i.test(name)) {
        names.add(safeVerifierText(name, MAX_STORED_NAME_CHARS));
        break;
      }
    }
    if (names.size >= MAX_COUNTED_FAILING_TESTS) break;
  }
  return { names: [...names].slice(0, MAX_FAILING_TESTS), total: names.size };
}

/**
 * Structured evidence of a failed verifier run. A timed-out run is never classified. With failing tests named, the
 * run reached the candidate, so exit 126/127 and environment-shaped text prove nothing. Otherwise ENVIRONMENT needs
 * exit 126/127, an executor failure with no exit code, or environment-shaped output from a run that printed no
 * runner summary.
 */
export function attemptEvidence(
  output: string,
  exitCode?: number | null,
  opts: { timedOut?: boolean; executorFailed?: boolean } = {},
): Pick<VerificationAttempt, "classification" | "exitCode" | "failingTests" | "failingTotal" | "failingTruncated" | "excerpt"> {
  const text = stripAnsi(output);
  const { names: failingTests, total } = failingTestScan(text);
  const none = failingTests.length === 0;
  const environment =
    !opts.timedOut &&
    none &&
    (exitCode === 126 ||
      exitCode === 127 ||
      (opts.executorFailed === true && typeof exitCode !== "number") ||
      (!RUNNER_SUMMARY.test(text) && ENVIRONMENT_OUTPUT.some((re) => re.test(text))));
  let excerpt = redactSecrets(text.trim());
  if (Buffer.byteLength(excerpt) > MAX_ATTEMPT_EXCERPT_BYTES) {
    excerpt = Buffer.from(excerpt).subarray(-MAX_ATTEMPT_EXCERPT_BYTES).toString("utf8").replace(/^\uFFFD+/, "");
  }
  return {
    ...(opts.timedOut ? {} : { classification: environment ? "ENVIRONMENT" : "CANDIDATE_FAILED" }),
    ...(typeof exitCode === "number" ? { exitCode } : {}),
    ...(failingTests.length ? { failingTests, failingTotal: total, ...(total > failingTests.length ? { failingTruncated: true } : {}) } : {}),
    ...(excerpt ? { excerpt } : {}),
  } as Pick<VerificationAttempt, "classification" | "exitCode" | "failingTests" | "failingTotal" | "failingTruncated" | "excerpt">;
}

/** One line for the model: classification, exit code and a few quoted failing test names (never the excerpt). */
export function describeAttemptEvidence(a: Pick<VerificationAttempt, "classification" | "exitCode" | "failingTests">): string {
  const parts: string[] = [];
  if (a.classification === "ENVIRONMENT") parts.push("ENVIRONMENT (the verifier could not run; this is not a candidate failure)");
  else if (a.classification) parts.push(a.classification);
import { test } from "node:test";
import assert from "node:assert/strict";
import { createLedger, recordAttempt, type ObjectiveLedger } from "../src/core/objective.js";
import {
  authoriseObligation, minimiseObligation, recordTestEdit, replayCommands, unmetObligations,
  authoriseReference, agreementStatement, differentialStatus,
} from "../src/core/regression_obligations.js";

const CMD = "npm test";
const failing = (ledger: ObjectiveLedger, tests: string[], inputs: string, extra: object = {}) =>
  recordAttempt(ledger, { command: CMD, inputs, status: "FAILED", classification: "CANDIDATE_FAILED", exitCode: 1, failingTests: tests, failedCheck: tests[0], ...extra });
const passing = (ledger: ObjectiveLedger, inputs: string, command = CMD) =>
  recordAttempt(ledger, { command, inputs, status: "PASSED" });

test("an unauthorised promotion cannot happen", () => {
  const ledger = createLedger("fix it");
  const a = failing(ledger, ["parses empty input"], "c1");
  assert.equal(ledger.obligations, undefined, "a failing attempt alone creates nothing");
  assert.throws(() => authoriseObligation(ledger, { authority: "model" as never, attempt: a.n, testName: "parses empty input" }), /operator/);
  assert.equal(ledger.obligations, undefined);
  // not a confirmed failure
  const env = recordAttempt(ledger, { command: CMD, inputs: "c2", status: "FAILED", classification: "ENVIRONMENT", exitCode: 127, failingTests: ["x"] });
  assert.equal(authoriseObligation(ledger, { authority: "operator", attempt: env.n, testName: "x" }).ok, false);
  const p = passing(ledger, "c3");
  assert.equal(authoriseObligation(ledger, { authority: "operator", attempt: p.n, testName: "parses empty input" }).ok, false);
  assert.equal(authoriseObligation(ledger, { authority: "operator", attempt: a.n, testName: "no such test" }).ok, false);
  assert.equal(ledger.obligations, undefined);
});

test("an authorised obligation keeps its failure record and is replayed on the next candidate", () => {
  const ledger = createLedger("fix it");
  const a = failing(ledger, ["parses empty input"], "c1", { excerpt: "AssertionError" });
  const res = authoriseObligation(ledger, { authority: "operator", attempt: a.n, testName: "parses empty input" });
  assert.equal(res.ok, true);
  const ob = ledger.obligations![0];
  assert.equal(ob.failureRecord.attempt, a.n);
  assert.equal(ob.failureRecord.excerpt, "AssertionError");
  assert.deepEqual(replayCommands(ledger), [CMD]);
  assert.equal(unmetObligations(ledger).length, 1, "never replayed yet");
  failing(ledger, ["parses empty input"], "c2");
  assert.equal(ob.replays.at(-1)?.outcome, "fail");
  passing(ledger, "c3", "other command");
  assert.equal(ob.replays.length, 1, "a different command is not a replay");
  recordAttempt(ledger, { command: CMD, inputs: "c4", status: "FAILED", classification: "ENVIRONMENT", exitCode: 127, failingTests: ["unrelated"] });
  assert.equal(ob.replays.length, 1, "an environment failure is not a replay");
  passing(ledger, "c5");
  assert.equal(ob.replays.at(-1)?.outcome, "pass");
  assert.equal(unmetObligations(ledger).length, 0);
  failing(ledger, ["something else"], "c6");
  assert.equal(ob.replays.at(-1)?.outcome, "pass", "the obligation's own test still passes when another fails");
});

test("minimising keeps the original failure record", () => {
  const ledger = createLedger("fix it");
  const a = failing(ledger, ["big scenario"], "c1");
  authoriseObligation(ledger, { authority: "operator", attempt: a.n, testName: "big scenario" });
  const b = failing(ledger, ["tiny scenario"], "c2");
  assert.equal(minimiseObligation(ledger, "RO1", { attempt: b.n, testName: "tiny scenario" }).ok, true);
  const ob = ledger.obligations![0];
  assert.equal(ob.testName, "tiny scenario");
  assert.equal(ob.failureRecord.failingTests?.[0], "big scenario");
  assert.equal(ob.failureRecord.testName, "big scenario");
  assert.equal(ob.history[0].from.testName, "big scenario");
  assert.equal(minimiseObligation(ledger, "RO1", { attempt: b.n, testName: "never failed" }).ok, false);
});

test("weakening edits to an obligation's test are recorded; strengthening is not", () => {
  const ledger = createLedger("fix it");
