export const MAX_IMPORT_DEPTH = 5;
const MAX_FILE_BYTES = 64 * 1024;
const MAX_TOTAL_BYTES = 256 * 1024;

export interface ExpandedRules {
  /** The instruction text with `@path` imports replaced by the imported files' contents. */
  text: string;
