  await withServer((seen) => (seen.noted ? nativeCall : textCall), async (client) => {
    await client.chatCompletion([user("run echo ok")], only("run_command"));
    assert.deepEqual(client.getLastUsage(), { inputTokens: 20, outputTokens: 4 });
