export interface ExecutionResult {
  success: boolean;
  output: string;
  error?: string;
  /** The operation's deadline expired before an answer was received (bridge-level; the runner reports its own via `timed_out`). */
  timedOut?: boolean;
  /** The operator's cancel ended the operation (the runner ended the command's process group). */
  cancelled?: boolean;
  /** Why the call was refused before it ran (a stable code, e.g. VERIFICATION_CONFIG_PROTECTED). */
  denialReason?: string;
}

/**
 * Bounds for automatically continued work. The total-step limit is cumulative across every invocation that continues
 * the same durable objective; the wall-clock limit bounds one active invocation. Progress detection remains a separate
 * early-stop mechanism, not a substitute for these hard ceilings.
 */
export interface ContinuationBudget {
  /** Maximum steps for one objective across runs and resumes (STEP_BUDGET_EXHAUSTED). */
  maxTotalSteps: number;
  /** Maximum wall-clock minutes for one invocation (TIME_BUDGET_EXHAUSTED). */
  maxTurnMinutes: number;
  /**
   * Consecutive steps without observed progress before the turn stops (STAGNATION_DETECTED). A repeated-state
   * threshold, not a task length: any progressing step resets it (core/execution_tracking.ts defines progress).
   */
  stagnationSteps: number;
  /** Recovery notes the agent may inject for a repeated identical action before stopping (bounded recovery). */
  maxRecoveries: number;
  /** Times the agent may be asked to continue when it stops with acceptance requirements still open. */
  maxCompletionNudges: number;
  /**
   * Consecutive failed verifier attempts on changing candidates that stop the turn as VERIFIER_NOT_CONVERGING when they
   * show the same failure, an A/B alternation or a rising failing-test count (default 3, NEXUS_VERIFIER_CONVERGENCE_ATTEMPTS).
   */
  verifierConvergenceAttempts?: number;
}

/** Hard upper bounds keep an operator override finite even when a config or direct API caller bypasses CLI parsing. */
export const MAX_CONTINUATION_STEPS = 5_000;
export const MAX_CONTINUATION_MINUTES = 4_320;

export function assertValidContinuationBudget(budget: ContinuationBudget | undefined): void {
  if (!budget) return;
  if (!Number.isSafeInteger(budget.maxTotalSteps) || budget.maxTotalSteps < 1 || budget.maxTotalSteps > MAX_CONTINUATION_STEPS) {
    throw new Error(`Invalid continuation step budget: expected an integer from 1 to ${MAX_CONTINUATION_STEPS}.`);
  }
  if (!Number.isFinite(budget.maxTurnMinutes) || budget.maxTurnMinutes < 1 / 60 || budget.maxTurnMinutes > MAX_CONTINUATION_MINUTES) {
    throw new Error(`Invalid continuation time budget: expected a finite value from 1 second to ${MAX_CONTINUATION_MINUTES} minutes.`);
  }
}

/** Failed verifier attempts on changing candidates that show no convergence before the turn stops (see ContinuationBudget). */
export const DEFAULT_CONVERGENCE_ATTEMPTS = 3;

export const DEFAULT_CONTINUATION: ContinuationBudget = {
  maxTotalSteps: 500,
  maxTurnMinutes: 480,
  stagnationSteps: 12,
  maxRecoveries: 2,
  maxCompletionNudges: 2,
};

export type ApprovalMode = "auto" | "review" | "read-only";
import { createHash } from "node:crypto";
import { covered, mergeIntervals, overlaps, readRequests, type ReadCoverage } from "./observation_identity.js";

/**
 * Objective-scoped execution tracking: how many steps the work has taken (also used by configured continuation
 * budgets), what counted as progress, which actions recurred without it, what failed, and what Nexus did about it.
 * It lives in the objective ledger, so compaction (which rewrites the conversation only), follow-up turns on the same
 * objective (which amend the ledger) and restart (which restores the ledger) all keep it. A new objective starts a new
 * ledger and so new tracking; `/requirements clear` and `/clear` reset it explicitly.
 *
 * Progress is judged from three identities, never from tool-call equality alone:
 * - action identity: tool name and canonical arguments (key order, whitespace and call ids do not matter);
 * - outcome identity: success and the output with volatile tokens (timestamps, durations, uuids, addresses, request
 *   ids, temporary paths) normalized away, so a changed clock in the output is not new information;
 * - state identity: the workspace's content identity (candidate identity: HEAD plus content of changed and untracked
 *   files), the git index, the content of dependency/environment inputs git ignores, and the PATH. Content, not
 *   mtimes: rewriting a file with identical content changes nothing. When it cannot be established it is "unknown"
 *   and every judgement that depends on it says so instead of asserting the state is unchanged.
 *
 * A step progressed when it reached a workspace state not seen before on this objective, observed something new (an
 * action/outcome/state triple not seen before, from an action that observes rather than mutates), changed the
 * acceptance ledger to a state not seen before, or applied operator input. Plan edits, re-formatted arguments, new
 * tool-call ids, re-writing identical content and returning to an earlier state are not progress.
 *
 * Storage is bounded. Repetition records that show a recurrence (count >= 2) are never evicted for a single-count
 * record; seen-sets are kept as 16-hex digests (MAX_SEEN each), oldest first out, with the number evicted recorded.
 * A loop must recur on the same triple, so it is caught by its repetition record however long the objective runs.
