/** Provider-owned refresh of a Nexus-owned OAuth credential (one attempt). */
const refreshing = new Map<string, Promise<StoredCredential>>();

/**
 * Refreshes a sign-in. Concurrent refreshes of the same provider and refresh token share one request: a rotating refresh
 * token is consumed by its first use, so a second request with it fails (invalid_grant) and the two results could be saved
 * out of order (I-AUTH-5). Calls with a different signal share too; an abort of the shared request fails all its waiters,
 * and a later call starts a new one. (Another process refreshing the same sign-in is not covered here.)
 */
export function refreshOAuth(providerId: string, cred: Extract<StoredCredential, { type: "oauth" }>, ep: OAuthEndpoints = endpoints, signal?: AbortSignal): Promise<StoredCredential> {
  if (!cred.refresh) return Promise.reject(new Error("No refresh token: sign in again."));
  const key = `${providerId}\u0000${cred.refresh}`;
  const inFlight = refreshing.get(key);
  if (inFlight) return inFlight;
  const request = refreshOAuthOnce(providerId, cred, ep, signal).finally(() => { if (refreshing.get(key) === request) refreshing.delete(key); });
  refreshing.set(key, request);
  return request;
}

