async function refreshOAuthOnce(providerId: string, cred: Extract<StoredCredential, { type: "oauth" }>, ep: OAuthEndpoints, signal?: AbortSignal): Promise<StoredCredential> {
  if (!cred.refresh) throw new Error("No refresh token: sign in again.");
  if (providerId === "copilot") return copilotToken(cred.refresh, ep, signal);
  if (providerId === "chatgpt") {
    const body = await postForm(`${ep.chatgptIssuer}/oauth/token`, { grant_type: "refresh_token", refresh_token: cred.refresh, client_id: CHATGPT_CLIENT_ID }, {}, signal);
