    const backupResult = createPreMigrationBackup(process.env.HOME || "", ({ filesCopied, bytesCopied }) => {
      options?.onProgress?.(
        "pre_migration_backup",
        `Backup progress: ${filesCopied} files, ${bytesCopied} bytes copied.`,
      );
    });
    fs.mkdirSync(tmpDir, { mode:0o700 });
