diff --git a/cli/src/core/extension_capabilities.ts b/cli/src/core/extension_capabilities.ts
new file mode 100644
index 00000000..c9ba2c19
--- /dev/null
+++ b/cli/src/core/extension_capabilities.ts
@@ -0,0 +1,39 @@
+/**
+ * Capabilities for tools that arrive at runtime from MCP servers and plugins.
+ *
+ * The execution spine refuses any tool that is not in the CapabilityRegistry (FAIL-001). MCP and plugin tools are
+ * discovered after construction, so they must be registered with an explicit effect class or every call to them is
+ * refused (audit D1, docs/INVARIANTS.md I-AUTH-2). Nothing is known about what a third-party tool does, so the
+ * defaults are the conservative ones: it is treated as mutating (read-only sessions refuse it) and its effect class is
+ * one that review mode asks the operator about (`egress` for a remote server, `exec` for a local process or plugin).
+ * Only a tool that runs in this machine's own process space can change the workspace; a remote server cannot, so only
+ * those make a verifier result stale.
+ */
+import type { ToolDefinition } from "../types.js";
+import type { CanonicalCapability } from "./capabilities.js";
+
+export type ExtensionOrigin =
+  | { kind: "mcp"; serverName: string; url?: string; command?: string }
+  | { kind: "plugin" };
+
+export function extensionCapability(definition: ToolDefinition, origin: ExtensionOrigin): CanonicalCapability {
+  const name = definition.function.name;
+  const remote = origin.kind === "mcp" && Boolean(origin.url) && !origin.command;
+  const from = origin.kind === "mcp" ? `MCP server '${origin.serverName}'` : "a plugin";
+  return {
+    id: `ext_${name}`,
+    modelToolName: name,
+    category: "extension",
+    mutating: true,
+    effect: remote ? "egress" : "exec",
+    changesWorkspace: !remote,
+    sideEffectContract: `Provided by ${from}; effects are not known to Nexus, so it is treated as ${remote ? "sending data off this machine" : "running local code"}.`,
+    backend: "extension",
+    toolDefinition: definition,
+  };
+}
+
+/** The registry keys of every extension capability currently registered. */
+export function isExtensionCapability(capability: Pick<CanonicalCapability, "category">): boolean {
+  return capability.category === "extension";
+}
diff --git a/cli/test/completion_receipt_binding.test.ts b/cli/test/completion_receipt_binding.test.ts
new file mode 100644
index 00000000..a9119b41
--- /dev/null
+++ b/cli/test/completion_receipt_binding.test.ts
@@ -0,0 +1,69 @@
+/**
+ * The validation receipt written at task_completed binds the verifier's real output (docs/INVARIANTS.md I-ACCEPT-1).
+ * Before, stdoutHash was the hash of the constant "VERIFIED_BY_TASK_COMPLETED": two different verifier outputs produced
+ * the same receipt, so the receipt could not show which run it described.
+ *
+ * Provenance: audit 2026-11-17 (agent.ts task_completed handler).
+ */
+import "./helpers/leak_guard.js";
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import fs from "node:fs";
+import http from "node:http";
+import os from "node:os";
+import path from "node:path";
+import { createHash } from "node:crypto";
+import { execSync } from "node:child_process";
+import { AutonomousAgent } from "../src/agent.js";
+
+async function completeWithVerifierOutput(marker: string): Promise<{ receiptHash: string; constantHash: string }> {
+  const base = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-receipt-"));
+  const repo = path.join(base, "repo");
+  fs.mkdirSync(repo);
+  execSync("git init -q", { cwd: repo, stdio: "ignore" });
+  execSync('git config user.name "Nexus Test" && git config user.email "nexus@example.invalid"', { cwd: repo, stdio: "ignore" });
+  fs.writeFileSync(path.join(repo, "base.txt"), "base\n");
+  fs.writeFileSync(path.join(repo, "Makefile"), `test:\n\t@echo ${marker}\n`);
+  execSync("git add . && git commit -qm baseline", { cwd: repo, stdio: "ignore" });
+  let requests = 0;
+  const server = http.createServer((req, res) => {
+    if (req.headers["x-nexus-purpose"] === "capabilities") { res.setHeader("content-type", "application/json"); res.end('{"data":[]}'); return; }
+    requests++;
+    req.resume();
+    req.on("end", () => {
+      const calls = [
+        { index: 0, id: "w", type: "function", function: { name: "write_file", arguments: JSON.stringify({ path: "change.txt", content: "x\n" }) } },
+        { index: 1, id: "c", type: "function", function: { name: "task_completed", arguments: JSON.stringify({ summary: "done" }) } },
+      ];
+      res.writeHead(200, { "Content-Type": "text/event-stream" });
+      res.end(`data: ${JSON.stringify({ choices: [{ delta: { content: "go", tool_calls: calls } }] })}\n\ndata: [DONE]\n\n`);
+    });
+  });
+  let agent: AutonomousAgent | undefined;
+  try {
+    const port = await new Promise<number>((r) => server.listen(0, "127.0.0.1", () => r((server.address() as any).port)));
+    agent = new AutonomousAgent({ endpoint: `http://127.0.0.1:${port}/v1`, model: "test", maxSteps: 2, temperature: 0, workspace: repo, shell: "bash", worktree: true, authoritativeVerifierCommand: "make test", approvalMode: "auto", fullAccess: true });
+    (agent as any).ui = new Proxy({}, { get: () => () => {} });
+    await agent.run("write a file");
+    const receipt = (agent as any).activeValidationReceipt;
+    assert.ok(receipt, "a validation receipt was recorded");
+    return {
+      receiptHash: receipt.stdoutHash,
+      
+      constantHash: createHash("sha256").update("VERIFIED_BY_TASK_COMPLETED").digest("hex"),
+    };
+  } finally {
+    if (agent?.getActiveWorktree()) agent.discardActiveWorktree();
+    agent?.shutdown();
+    server.closeAllConnections();
+    await new Promise<void>((r) => server.close(() => r()));
+    fs.rmSync(base, { recursive: true, force: true });
+  }
+}
+
+test("the completion receipt hashes the verifier's actual output, so different runs give different receipts", async () => {
+  const a = await completeWithVerifierOutput("output-alpha");
+  const b = await completeWithVerifierOutput("output-bravo");
+  assert.notEqual(a.receiptHash, a.constantHash);
+  assert.notEqual(a.receiptHash, b.receiptHash);
+});
