+ * (docs/INVARIANTS.md I-PROVIDER-1). Provenance: audit 2026-11-17 (runSubagent never called refreshCapabilities, so a
+ * helper on a 40k-context model was admitted against the default window).
+ */
+import "./helpers/leak_guard.js";
