+import assert from "node:assert/strict";
+import fs from "node:fs";
+import os from "node:os";
+import path from "node:path";
+import { AutonomousAgent } from "../src/agent.js";
+import { DEFAULT_CONTINUATION, type HarnessConfig } from "../src/types.js";
+import { startGateway, makeRepo } from "./helpers/fixtures.js";
+
+let home = "";
+let previousHome: string | undefined;
+before(() => { previousHome = process.env.HOME; home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-subcap-home-")); process.env.HOME = home; });
+after(() => { if (previousHome === undefined) delete process.env.HOME; else process.env.HOME = previousHome; fs.rmSync(home, { recursive: true, force: true }); });
+
+const isSub = (b: any) => JSON.stringify(b?.messages ?? []).includes("[Subagent Objective]");
+const results = (b: any) => (b?.messages ?? []).filter((m: any) => m.role === "tool").length;
+
+test("a subagent discovers its connection's context limit", { timeout: 60_000 }, async () => {
+  const repo = makeRepo({ "notes.txt": "hello\n" });
+  const seen: Array<number | undefined> = [];
+  const original = (AutonomousAgent.prototype as any).admitWithFindings;
+  (AutonomousAgent.prototype as any).admitWithFindings = async function (this: any, ...args: unknown[]) {
+    if (this.runningAsSubagent) seen.push(this.capabilities?.contextLimit ?? this.contextLimit());
+    return original.apply(this, args);
+  };
+  const gw = await startGateway((_n, body) => {
+    if (!body?.tools) return { kind: "text", content: "No findings." };
+    if (isSub(body)) return results(body) === 0 ? { kind: "tools", calls: [{ name: "read_file", args: { path: "notes.txt" } }] } : { kind: "text", content: "report" };
+    return results(body) === 0 ? { kind: "tools", calls: [{ name: "spawn_subagent", args: { prompt: "Read notes.txt." } }] } : { kind: "text", content: "done" };
+  }, { models: () => [{ id: "m", context_length: 24_000, max_model_len: 24_000 }] });
+  const config: HarnessConfig = { endpoint: gw.url, model: "m", maxSteps: 12, temperature: 0, workspace: repo, shell: "bash", continuation: { ...DEFAULT_CONTINUATION }, approvalMode: "auto", fullAccess: true };
+  const agent = new AutonomousAgent(config);
+  (agent as any).ui = new Proxy({}, { get: () => () => {} });
+  const log = console.log; console.log = () => {};
+  try {
+    await agent.runTurn("Use a subagent to read notes.txt.");
+    assert.ok(seen.length >= 1, "the subagent ran at least one admission");
+    assert.ok(seen.every((limit) => limit === 24_000), `subagent admission used limits ${JSON.stringify(seen)}, expected the advertised 24000`);
+  } finally {
+    console.log = log;
+    (AutonomousAgent.prototype as any).admitWithFindings = original;
+    agent.shutdown();
+    await gw.close();
+    fs.rmSync(repo, { recursive: true, force: true });
+  }
+});

